  `project_id` int NOT NULL,
  `admin_panel` tinyint(1) DEFAULT '1',
  `menu_display` tinyint(1) DEFAULT '1',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `online_ordering_system` tinyint(1) DEFAULT '0',
  `catering_system` tinyint(1) DEFAULT '0',
  `booking_reservation_system` tinyint(1) DEFAULT '0',
  `staff_admin_system` tinyint(1) DEFAULT '0',
